//! Unit tests for internals. Expected values come from the JS, not from this
//! crate: the tables in `oracle_data.rs` are generated by `oracle/gen.js`
//! running metro-file-map's real `TreeFS` / `RootPathUtils`, and the
//! PackageCache and JSON expectations below were produced by running Metro's
//! `PackageCache` and `JSON.parse` with `node -e` against this checkout
//! (`unstable_registerForMetroMonorepo`).

use crate::oracle_data::*;
use crate::*;
use serde_json::Value;
use std::cell::Cell;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::rc::Rc;
use std::sync::Arc;

fn oracle_store() -> FileStore {
    let mut fs = FileStore::new(ROOT);
    let mut entries: Vec<(&str, EntryKind)> = FILES.iter().map(|f| (*f, EntryKind::File)).collect();
    entries.extend(
        LINKS
            .iter()
            .map(|(k, t)| (*k, EntryKind::Symlink { target: t })),
    );
    fs.bulk_add(entries).unwrap();
    fs
}

fn show(l: Lookup) -> String {
    match l {
        Lookup::NotFound => "N".into(),
        Lookup::File { real_path } => format!("F:{real_path}"),
        Lookup::Dir { real_path } => format!("D:{real_path}"),
    }
}

#[test]
fn lookup_matches_js_treefs() {
    let fs = oracle_store();
    for (q, want) in LOOKUPS {
        assert_eq!(show(fs.lookup(q)), *want, "lookup({q:?})");
    }
}

#[test]
fn exists_matches_js_treefs() {
    let fs = oracle_store();
    for (q, want) in EXISTS {
        assert_eq!(fs.exists(q), *want, "exists({q:?})");
    }
}

#[test]
fn hierarchical_lookup_matches_js_treefs() {
    let fs = oracle_store();
    for (start, sub, dir, brk, want) in HIER {
        let got = catch_unwind(AssertUnwindSafe(|| {
            fs.hierarchical_lookup(start, sub, *brk, *dir)
        }));
        let ctx = format!("hierarchical_lookup({start:?}, {sub:?}, {brk:?}, dir={dir})");
        match want {
            // JS throws the 'Failed to collapse' invariant; Rust panics there.
            Hier::Throw => assert!(got.is_err(), "{ctx} should fail like the JS"),
            Hier::None => assert_eq!(got.unwrap(), None, "{ctx}"),
            Hier::Some(a, c) => {
                assert_eq!(got.unwrap(), Some((a.to_string(), c.to_string())), "{ctx}")
            }
        }
    }
}

#[test]
fn mutations_match_js_treefs() {
    for (op, p, target, want) in MUTATIONS {
        let mut fs = oracle_store();
        let res = match *op {
            "remove" => {
                fs.remove(p);
                Ok(())
            }
            "add" => fs.add_or_modify(p, EntryKind::File),
            "addlink" => fs.add_or_modify(p, EntryKind::Symlink { target }),
            _ => unreachable!(),
        };
        let got = match res {
            Err(_) => vec!["THROW".to_string()],
            Ok(()) => fs.metadata_iterator(),
        };
        assert_eq!(got, *want, "{op}({p:?})");
    }
}

#[test]
fn root_path_utils_matches_js() {
    for (root, func, a, b, want) in RPU {
        let u = RootPathUtils::new(root);
        let got = match *func {
            "absoluteToNormal" => u.absolute_to_normal(a),
            "normalToAbsolute" => u.normal_to_absolute(a),
            "relativeToNormal" => u.relative_to_normal(a),
            "resolveSymlinkToNormal" => u.resolve_symlink_to_normal(a, b),
            "joinNormalToRelative" => {
                match catch_unwind(AssertUnwindSafe(|| u.join_normal_to_relative(a, b))) {
                    Ok(r) => format!("{}|{}", r.normal_path, r.collapsed_segments),
                    Err(_) => "THROW".to_string(),
                }
            }
            _ => unreachable!(),
        };
        assert_eq!(got, *want, "{root} {func}({a:?}, {b:?})");
    }
}

#[test]
fn root_parts_and_ancestor_basenames() {
    // JS: new RootPathUtils('/proj/root').getParts() is ['', 'proj', 'root'],
    // getBasenameOfNthAncestor(0) 'root', (1) 'proj'; for '/' parts are [''].
    let u = RootPathUtils::new("/proj/root");
    assert_eq!(u.get_parts(), ["", "proj", "root"]);
    assert_eq!(u.get_basename_of_nth_ancestor(0), "root");
    assert_eq!(u.get_basename_of_nth_ancestor(1), "proj");
    assert_eq!(RootPathUtils::new("/").get_parts(), [""]);
}

#[test]
fn symlink_cycle_and_broken_links_are_not_found() {
    let mut fs = FileStore::new("/p");
    fs.bulk_add([
        ("c1", EntryKind::Symlink { target: "c2" }),
        ("c2", EntryKind::Symlink { target: "c1" }),
        ("self", EntryKind::Symlink { target: "self" }),
        ("f.js", EntryKind::File),
    ])
    .unwrap();
    assert_eq!(fs.lookup("c1"), Lookup::NotFound);
    assert_eq!(fs.lookup("self/x"), Lookup::NotFound);
    assert!(!fs.exists("c2"));
    assert_eq!(fs.link_is_regular_file("c1"), Some(false));
    assert_eq!(fs.link_is_regular_file("f.js"), Some(true));
}

#[test]
fn ids_are_stable_and_never_reused() {
    let mut fs = FileStore::new("/p");
    fs.bulk_add([("a/f.js", EntryKind::File)]).unwrap();
    let id = fs.file_id("a/f.js", true).unwrap();
    fs.add_or_modify("a/f.js", EntryKind::Symlink { target: "x" })
        .unwrap();
    assert_eq!(fs.file_id("a/f.js", false), Some(id), "modify keeps the id");
    fs.remove("a/f.js");
    assert_eq!(fs.file_id("a/f.js", false), None);
    fs.add_or_modify("a/f.js", EntryKind::File).unwrap();
    let id2 = fs.file_id("a/f.js", true).unwrap();
    assert_ne!(id, id2, "removed ids are not reused");
}

#[test]
fn removal_prunes_empty_parents_but_not_the_root() {
    let mut fs = FileStore::new("/p/q");
    fs.bulk_add([
        ("a/b/c/d.js", EntryKind::File),
        ("../x/y.js", EntryKind::File),
    ])
    .unwrap();
    fs.remove("/p/q/a/b/c/d.js");
    assert!(fs.metadata_iterator() == ["../x/y.js|f"]);
    assert_eq!(fs.lookup("a"), Lookup::NotFound);
    fs.remove("../x/y.js");
    assert!(fs.metadata_iterator().is_empty());
    // The detached '..' directory still reads as a directory (JS quirk).
    assert_eq!(
        fs.lookup(".."),
        Lookup::Dir {
            real_path: "/p".into()
        }
    );
}

#[test]
fn add_errors_mirror_js_throws() {
    let mut fs = FileStore::new("/p");
    fs.bulk_add([("f.js", EntryKind::File)]).unwrap();
    let e = fs.bulk_add([("f.js/x", EntryKind::File)]).unwrap_err();
    assert!(
        e.0.contains("already exists in the file map as a file"),
        "{e}"
    );
    assert!(fs.add_directory("f.js").is_err());
    assert!(fs.add_directory("d/e").is_ok());
    assert_eq!(
        fs.lookup("d/e"),
        Lookup::Dir {
            real_path: "/p/d/e".into()
        }
    );
}

#[test]
fn change_batch_order_replaces_kinds_and_invalidates() {
    let mut fs = FileStore::new("/r");
    fs.bulk_add([
        ("d/old.js", EntryKind::File),
        ("d/sub/x.js", EntryKind::File),
        ("f", EntryKind::File),
        ("pkg/package.json", EntryKind::File),
    ])
    .unwrap();
    // directory `d` becomes a file, file `f` becomes a directory
    fs.apply_change_batch(
        &["f".to_string()],
        &["d".to_string()],
        &["f".to_string()],
        &[("d", EntryKind::File), ("f/inner.js", EntryKind::File)],
    )
    .unwrap();
    assert_eq!(
        fs.metadata_iterator(),
        ["d|f", "f/inner.js|f", "pkg/package.json|f"]
    );
    // a directory removed and recreated in one batch keeps no stale children
    fs.apply_change_batch(
        &[],
        &["f".to_string()],
        &["f".to_string()],
        &[("f/new.js", EntryKind::File)],
    )
    .unwrap();
    assert_eq!(
        fs.metadata_iterator(),
        ["d|f", "f/new.js|f", "pkg/package.json|f"]
    );
}

// ---------------------------------------------------------------------------
// JSON
// ---------------------------------------------------------------------------

fn keys(v: &Value) -> Vec<&str> {
    v.as_object().unwrap().keys().map(String::as_str).collect()
}

#[test]
fn json_key_order_duplicates_and_numbers_match_js() {
    // Expected from node: Object.keys(JSON.parse(text)) and friends.
    let text = r#"{"b":1,"2":2,"a":{"10":1,"9":2,"x":3},"1":[{"z":1,"0":2}],"01":0,"4294967294":1,"4294967295":2,"a":9,"-1":0,"1.5":1,"__proto__":5,"dup":1,"k":2,"dup":3}"#;
    let v = parse_like_js(text).unwrap();
    assert_eq!(
        keys(&v),
        [
            "1",
            "2",
            "4294967294",
            "b",
            "a",
            "01",
            "4294967295",
            "-1",
            "1.5",
            "__proto__",
            "dup",
            "k"
        ]
    );
    // last value wins, in the position of the first occurrence
    assert_eq!(v["a"], Value::from(9));
    assert_eq!(v["dup"], Value::from(3));
    assert_eq!(keys(&v["1"][0]), ["0", "z"]);
    let w = parse_like_js(r#"{"x":{"b":1,"a":2,"b":3}}"#).unwrap();
    assert_eq!(keys(&w["x"]), ["b", "a"]);
    assert_eq!(w["x"]["b"], Value::from(3));
    // JSON.parse('[12345678901234567890, 9007199254740993, -9007199254740993]')
    // is [12345678901234567000, 9007199254740992, -9007199254740992]
    let n =
        parse_like_js("[12345678901234567890, 9007199254740993, -9007199254740993, 0.1]").unwrap();
    let f: Vec<f64> = n
        .as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect();
    assert_eq!(
        f,
        [
            12345678901234567890f64,
            9007199254740992.0,
            -9007199254740992.0,
            0.1
        ]
    );
}

#[test]
fn array_index_keys() {
    assert_eq!(array_index("0"), Some(0));
    assert_eq!(array_index("12"), Some(12));
    assert_eq!(array_index("01"), None);
    assert_eq!(array_index("4294967294"), Some(4294967294));
    assert_eq!(array_index("4294967295"), None);
    assert_eq!(array_index("-1"), None);
    assert_eq!(array_index(""), None);
    assert_eq!(array_index("1e3"), None);
}

#[test]
fn json_parse_failures_are_deferred() {
    // Each of these is accepted or rejected by JSON.parse in a way Rust must
    // not decide: lone surrogate (JS accepts), BOM (JS rejects), depth,
    // out-of-range number (JS: Infinity), empty and trailing garbage.
    for text in [
        r#"{"a":"\ud800"}"#,
        "\u{feff}{}",
        "",
        "{} x",
        "1e999",
        &"[".repeat(200),
    ] {
        assert!(parse_like_js(text).is_err(), "{text:?}");
    }
    assert!(parse_like_js("null").is_ok());
    assert!(parse_like_js(" \t\n\r{\"a\":[1,2]}\n").is_ok());
}

struct TempDir(std::path::PathBuf);

impl TempDir {
    fn new(name: &str) -> Self {
        let p =
            std::env::temp_dir().join(format!("metro-rs-file-store-{}-{name}", std::process::id()));
        let _ = std::fs::remove_dir_all(&p);
        std::fs::create_dir_all(&p).unwrap();
        TempDir(p)
    }
    fn write(&self, name: &str, bytes: &[u8]) -> String {
        let p = self.0.join(name);
        std::fs::write(&p, bytes).unwrap();
        p.to_str().unwrap().to_string()
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

#[test]
fn get_package_reads_real_files_and_defers_when_unsure() {
    let dir = TempDir::new("defer");
    let fs = FileStore::new("/unused");
    let ok = dir.write("ok.json", br#"{"name":"x","2":1,"1":2}"#);
    let StoreAnswer::Answer(Some(pj)) = fs.get_package(&ok) else {
        panic!("expected an answer")
    };
    assert_eq!(keys(&pj), ["1", "2", "name"]);
    // cached: the same Arc comes back
    let StoreAnswer::Answer(Some(again)) = fs.get_package(&ok) else {
        panic!()
    };
    assert!(Arc::ptr_eq(&pj, &again));

    let null = dir.write("null.json", b"null");
    assert_eq!(fs.get_package(&null), StoreAnswer::Answer(None));
    let bad_utf8 = dir.write("bad.json", b"{\"a\":\"\xff\"}");
    let bom = dir.write("bom.json", b"\xef\xbb\xbf{}");
    let surrogate = dir.write("sur.json", br#"{"a":"\udc00"}"#);
    let syntax = dir.write("syntax.json", b"{");
    let missing = dir.0.join("missing.json").to_str().unwrap().to_string();
    for p in [bad_utf8, bom, surrogate, syntax, missing] {
        assert_eq!(fs.get_package(&p), StoreAnswer::Defer, "{p}");
    }
}

// ---------------------------------------------------------------------------
// PackageCache
// ---------------------------------------------------------------------------

/// The scenario mirrors one run of Metro's `PackageCache` (expected values
/// from node): tuples are (step, "root|relative|readN" or "null" or "THROW",
/// reader calls so far).
const PACKAGE_CACHE_STEPS: &[(&str, &str, u32)] = &[
    ("gpm /r/a/x.js", "/r/a|x.js|read1", 1),
    ("gpm /r/a/x.js again", "/r/a|x.js|read1", 1),
    ("gpm /r/b/y.js", "null", 1),
    ("invalidate other.js; gpm /r/a/x.js", "/r/a|x.js|read1", 1),
    ("invalidate a/package.json; gpm x.js", "/r/a|x.js|read2", 2),
    ("gpm /r/a/sub/z.js", "/r/a|sub/z.js|read2", 2),
    (
        "new sub/package.json; gpm z.js (stale)",
        "/r/a|sub/z.js|read2",
        2,
    ),
    ("gpm y.js after null invalidated", "null", 2),
    (
        "add b/package.json, no invalidate; gpm y.js (stale null)",
        "null",
        2,
    ),
    ("invalidate b/package.json; gpm y.js", "/r/b|y.js|read3", 3),
    ("invalidate z.js; gpm z.js", "/r/a/sub|z.js|read4", 4),
    ("failing reader gpm /r/c/w.js", "THROW", 5),
    ("failing reader gpm /r/c/w.js again", "THROW", 6),
    ("reader fixed; gpm w.js", "/r/c|w.js|read7", 7),
    ("delete c/package.json; gpm w.js", "null", 7),
    ("node_modules break /r/a/node_modules/p/i.js", "null", 7),
];

#[test]
fn package_cache_invalidation_matches_js_including_staleness() {
    let mut fs = FileStore::new("/r");
    fs.bulk_add([("a/package.json", EntryKind::File)]).unwrap();
    let reads = Rc::new(Cell::new(0u32));
    let failing = Rc::new(Cell::new(false));
    {
        let (reads, failing) = (reads.clone(), failing.clone());
        fs.set_package_reader(Box::new(move |p| {
            reads.set(reads.get() + 1);
            if failing.get() && p == "/r/c/package.json" {
                return Err(Defer);
            }
            Ok(Arc::new(
                serde_json::json!({"read": reads.get(), "path": p}),
            ))
        }));
    }
    let gpm = |fs: &FileStore, m: &str| match fs.get_package_for_module(m) {
        StoreAnswer::Defer => "THROW".to_string(),
        StoreAnswer::Answer(None) => "null".to_string(),
        StoreAnswer::Answer(Some(r)) => format!(
            "{}|{}|read{}",
            r.root_path, r.package_relative_path, r.package_json["read"]
        ),
    };
    let mut got = Vec::new();
    let mut rec = |v: String| got.push((v, reads.get()));

    let v = gpm(&fs, "/r/a/x.js");
    rec(v);
    let v = gpm(&fs, "/r/a/x.js");
    rec(v);
    let v = gpm(&fs, "/r/b/y.js");
    rec(v);
    fs.invalidate_package("/r/a/other.js");
    let v = gpm(&fs, "/r/a/x.js");
    rec(v);
    fs.invalidate_package("/r/a/package.json");
    let v = gpm(&fs, "/r/a/x.js");
    rec(v);
    let v = gpm(&fs, "/r/a/sub/z.js");
    rec(v);
    // a closer package.json appears; the batch invalidates it
    fs.apply_change_batch(&[], &[], &[], &[("a/sub/package.json", EntryKind::File)])
        .unwrap();
    let v = gpm(&fs, "/r/a/sub/z.js");
    rec(v);
    let v = gpm(&fs, "/r/b/y.js");
    rec(v);
    // tree change without invalidation: the null result stays stale
    fs.add_or_modify("b/package.json", EntryKind::File).unwrap();
    let v = gpm(&fs, "/r/b/y.js");
    rec(v);
    fs.invalidate_package("/r/b/package.json");
    let v = gpm(&fs, "/r/b/y.js");
    rec(v);
    fs.invalidate_package("/r/a/sub/z.js");
    let v = gpm(&fs, "/r/a/sub/z.js");
    rec(v);
    failing.set(true);
    fs.add_or_modify("c/package.json", EntryKind::File).unwrap();
    let v = gpm(&fs, "/r/c/w.js");
    rec(v);
    let v = gpm(&fs, "/r/c/w.js");
    rec(v);
    failing.set(false);
    let v = gpm(&fs, "/r/c/w.js");
    rec(v);
    fs.apply_change_batch(&["c/package.json".to_string()], &[], &[], &[])
        .unwrap();
    let v = gpm(&fs, "/r/c/w.js");
    rec(v);
    let v = gpm(&fs, "/r/a/node_modules/p/i.js");
    rec(v);

    let want: Vec<(String, u32)> = PACKAGE_CACHE_STEPS
        .iter()
        .map(|(_, v, n)| (v.to_string(), *n))
        .collect();
    assert_eq!(got, want);

    // getPackage: JS `getPackage('/r/a/package.json')` twice gives read 2 both
    // times (cached since the step-5 re-read).
    let StoreAnswer::Answer(Some(a)) = fs.get_package("/r/a/package.json") else {
        panic!()
    };
    assert_eq!(a["read"], Value::from(2));
}

#[test]
fn null_package_json_is_cached_for_modules_but_reported_as_none() {
    let mut fs = FileStore::new("/r");
    fs.bulk_add([("a/package.json", EntryKind::File)]).unwrap();
    let reads = Rc::new(Cell::new(0));
    let r2 = reads.clone();
    fs.set_package_reader(Box::new(move |_| {
        r2.set(r2.get() + 1);
        Ok(Arc::new(Value::Null))
    }));
    // JS: `getPackage(p).packageJson ?? null` is null for a `null` file.
    assert_eq!(
        fs.get_package("/r/a/package.json"),
        StoreAnswer::Answer(None)
    );
    let StoreAnswer::Answer(Some(r)) = fs.get_package_for_module("/r/a/x.js") else {
        panic!()
    };
    assert!(r.package_json.is_null());
    assert_eq!(reads.get(), 1);
}

#[test]
fn random_trees_match_js_treefs() {
    for (n, (entries, queries, expected)) in RANDOM.iter().enumerate() {
        let mut fs = FileStore::new("/w/x/root");
        let parsed: Vec<(&str, EntryKind)> = entries
            .iter()
            .map(|e| match e.split_once("|l:") {
                Some((p, t)) => (p, EntryKind::Symlink { target: t }),
                None => (e.strip_suffix("|f").unwrap(), EntryKind::File),
            })
            .collect();
        fs.bulk_add(parsed).unwrap();
        for (q, want) in queries.iter().zip(*expected) {
            let hier = |sub: &str, dir: bool, brk: Option<&str>| match catch_unwind(
                AssertUnwindSafe(|| fs.hierarchical_lookup(q, sub, brk, dir)),
            ) {
                Err(_) => "THROW".to_string(),
                Ok(None) => "null".to_string(),
                Ok(Some((a, c))) => format!("{a}>{c}"),
            };
            let got = [
                show(fs.lookup(q)),
                fs.exists(q).to_string(),
                hier("package.json", false, Some("node_modules")),
                hier("node_modules/p", true, None),
            ]
            .join(";");
            assert_eq!(&got, want, "case {n}: {q:?}\nentries: {entries:?}");
        }
    }
}
